VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.31,"Phase nine. Fourier transform and the F F T. This is how every signal splits into waves."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":20.016,"caps":[[0.66,5.63,"Count the waves in one second."],[5.88,11.01,"Two waves added make one wiggle."],[11.26,15.51,"Each bar: which wave, and how strong."],[15.76,19.29,"One signal, two descriptions."]],"warp":[[0,0],[0.66,1.2],[5.88,3.7],[11.26,6.3],[15.76,8.4],[20.016,10.5]]},{"dur":30,"caps":[[0.5,4.67,"Target: a square wave."],[4.92,7.89,"Start with one sine wave."],[8.14,12.23,"Add a weaker wave, 3 times faster."],[12.48,16.57,"Then 5 times faster, weaker still."],[16.82,22.67,"Keep adding: the corners sharpen."],[22.92,28.77,"A square wave needs only odd waves."]],"warp":[[0,0],[0.5,0.6],[4.92,2],[8.14,3.4],[12.48,5.2],[16.82,6.9],[22.92,9.5],[30,11.5]]},{"dur":30,"caps":[[0.66,4.11,"To find the bars, take 8 samples."],[4.36,8.21,"Each sample scales a spinning arrow."],[8.46,13.35,"Zero makes no arrow. Negative flips it."],[13.6,19.77,"Right speed: they all lean right and add."],[20.02,22.51,"Now spin twice instead."],[22.76,27.89,"The arrows loop back and cancel."]],"warp":[[0,0],[0.66,1.2],[4.36,3.2],[8.46,5],[13.6,7.5],[20.02,11.1],[22.76,12.6],[30,16]]},{"dur":25.008,"caps":[[0.66,4.43,"Run the test at every spin speed."],[4.68,10.53,"Each test reads all 8 samples."],[10.78,15.27,"Eight tests give eight bars."],[15.52,19.85,"That is 8 × 8 = 64 products."],[20.1,24.03,"A real wave gives a mirror pair."]],"warp":[[0,0],[0.66,1.2],[4.68,3.2],[10.78,6.6],[15.52,8.3],[20.1,10],[25.008,12]]},{"dur":23.313,"caps":[[0.94,4.63,"Take 8 samples in one second."],[4.88,8.48,"The dots fit a 1 Hz wave too."],[8.73,12.11,"Half the sample rate is the limit."],[12.36,17.16,"So 7 Hz folds back onto 1 Hz."],[17.41,22.7,"Sample faster than twice the wave."]],"warp":[[0,0],[0.935,1.7],[4.875,3.4],[8.735,5.7],[12.355,7.5],[17.415,9.9],[23.313,12.5]]},{"dur":25.008,"caps":[[0.83,4.83,"The DFT repeats the window."],[5.08,8.7,"Whole cycles join: one clean bar."],[8.95,12.63,"Half a cycle more: the ends do not meet."],[12.88,18.81,"The jump needs many frequencies: the bars leak."],[19.06,24.19,"A smooth fade at both ends shrinks the leak."]],"warp":[[0,0],[0.825,1.5],[5.085,3],[8.945,4.5],[12.885,6.7],[19.065,9.3],[25.008,12]]},{"dur":21.664,"caps":[[1.43,6.32,"The DFT turns the wiggle into bars."],[6.57,9.86,"The hum is one pair of bars."],[10.11,13.64,"Delete both bars."],[13.89,20.46,"Go back: the hum fades away."]],"warp":[[0,0],[1.43,2.6],[6.57,4.2],[10.11,6],[13.89,8.4],[21.664,11.5]]},{"dur":28.398,"caps":[[0.83,5.16,"A full DFT does all 64 products."],[5.41,9.02,"Split into even and odd samples."],[9.27,13.28,"Two half-size DFTs cost 16 each."],[13.53,19.3,"One butterfly: one product, two answers."],[19.55,26.44,"32 plus 4 is 36 products, not 64."]],"warp":[[0,0],[0.825,1.5],[5.405,3.3],[9.265,5],[13.525,6.9],[19.545,9.2],[28.398,12.5]]},{"dur":37.036,"caps":[[0.5,4.75,"Each half is a DFT too: split again."],[5,9.41,"Down to single samples."],[9.66,14.71,"Butterflies combine pairs, level by level."],[14.96,18.57,"Three levels of four: 12 butterflies."],[18.82,23.39,"The same answer as the direct DFT."],[23.64,27.81,"Direct: 18 minutes for a million samples."],[28.06,31.83,"The FFT: 0.02 seconds."],[32.08,35.29,"About 50,000 times less work."]],"warp":[[0,0],[0.5,0.6],[5,2.5],[9.66,4.2],[14.96,7],[18.82,8.7],[23.64,11.3],[28.06,13.1],[32.08,14.4],[37.036,16.8]]},{"dur":14.976,"caps":[],"warp":[[0,0],[0.5,0.9],[4.28,2],[9.26,3.1],[14.976,9]]}]};
